// Lightweight data model sketch
class ProvenanceEntry {
  constructor(tenantId, promptHash, policyVersion, ts, action) {
    this.tenantId = tenantId;
    this.promptHash = promptHash;
    this.policyVersion = policyVersion;
    this.ts = ts;
    this.action = action;
  }
}
```

